urn False\n    \n    print(\"\\n\" + \"=\" * 70)\n    print(\"TEST 2: Unqualified lookup with modname='mod'\")\n    print(\"=\" * 70)\n    # Test 2: When current module is 'mod', looking for 'A'\n    # Should find 'mod.A' (most specific match in this context)\n    matches = domain.find_obj(env, 'mod', '', 'A', 'class', searchmode=0)\n    print(f\"Searching for 'A' with modname='mod', classname=''\")\n    print(f\"Matches found: {len(matches)}\")\n    if matches:\n        for fullname, objentry in matches:\n            print(f\"  -> {fullname} (from {objentry.docname})\")\n        expected = 'mod.A'\n        actual = matches[0][0]\n        if actual == expected:\n            print(f\"✓ PASS: Found '{actual}' as expected\")\n        else:\n            print(f\"✗ FAIL: Expected '{expected}', but got '{actual}'\")\n            return False\n    else:\n        print(\"✗ FAIL: No matches found\")\n        return False\n    \n    print(\"\\n\" + \"=\" * 70)\n    print(\"TEST 3: Bare name lookup with no module context\")\n    print(\"=\" * 70)\n    # Test 3: With no module context, should still find something\n    matches = domain.find_obj(env, '', '', 'A', 'class', searchmode=0)\n    print(f\"Searching for 'A' with no module context\")\n    print(f\"Matches found: {len(matches)}\")\n    if matches:\n        for fullname, objentry in matches:\n            print(f\"  -> {fullname} (from {objentry.docname})\")\n        # Without context, should fallback to bare name match\n        # Since we don't have a bare 'A' registered, it might not find anything\n        # Or it should try to match one of the qualified names\n        print(f\"✓ PASS: Found a match\")\n    else:\n        print(\"✓ PASS: No match without context (expected)\")\n    \n    print(\"\\n\" + \"=\" * 70)\n    print(\"TEST 4: Qualified name always works\")\n    print(\"=\" * 70)\n    # Test 4: Fully qualified names should always work\n    matches = domain.find_obj(env, 'mod', '', 'mod.submod.A', 'class', searchmo